// Kleiner Beispiel-Formatierer fuer das Video (kein Prettier):
// ersetzt doppelte durch einfache Anfuehrungszeichen und setzt eine Kopfzeile.
const fs = require("fs");
let d = "";
process.stdin.on("data", c => d += c).on("end", () => {
  const p = (JSON.parse(d).tool_input || {}).file_path || "";
  if (!p.endsWith(".js")) process.exit(0);
  let s = fs.readFileSync(p, "utf8").replace(/"/g, "'");
  if (!s.startsWith("// formatiert")) s = "// formatiert mit format.js\n" + s;
  fs.writeFileSync(p, s);
});
